const arquivo = await this.helpers.getBinaryDataBuffer(0, 'data');
const lojas = JSON.parse(arquivo.toString('utf8'));

if (!Array.isArray(lojas)) {
  throw new Error('O arquivo lojas.json deve conter uma lista de lojas.');
}

let periodos;

try {
  periodos = $('Períodos da demonstração').first().json.periodos;
} catch (erro) {
  // Este início não foi usado.
}

if (!periodos) {
  try {
    periodos = $('Período semanal').first().json.periodos;
  } catch (erro) {
    // Este início não foi usado.
  }
}

if (!periodos) {
  try {
    periodos = $('Período mensal').first().json.periodos;
  } catch (erro) {
    // Este início não foi usado.
  }
}

if (!Array.isArray(periodos)) {
  throw new Error('Não foi possível identificar o período do resumo.');
}

return [{
  json: {
    lojas,
    periodos
  }
}];

const arquivo = await this.helpers.getBinaryDataBuffer(0, 'data');
const recomendacoes = JSON.parse(arquivo.toString('utf8'));

if (!Array.isArray(recomendacoes)) {
  throw new Error('O arquivo recomendacoes.json deve conter uma lista.');
}

const dados = $('Interpretar resumos').first().json;

if (!Array.isArray(dados.lojas)) {
  throw new Error('A lista de lojas não foi encontrada.');
}

if (!Array.isArray(dados.periodos)) {
  throw new Error('A lista de períodos não foi encontrada.');
}

if (!Array.isArray(dados.resumos)) {
  throw new Error('A lista de resumos não foi encontrada.');
}

return dados.periodos.flatMap(periodo =>
  dados.lojas.map(loja => ({
    json: {
      loja,
      periodo: periodo.periodo,
      periodicidade: periodo.periodicidade,
      resumos: dados.resumos,
      recomendacoes
    }
  }))
);

