const x=$('Percorrer resumos').first().json,l=x.loja,agora=new Date().toISOString();const resumo=x.resumos.find(r=>r.loja_id===l.loja_id&&r.periodo===x.periodo&&r.periodicidade===x.periodicidade);const mes=x.periodo.slice(0,7);const rec=x.recomendacoes.find(r=>r.loja_id===l.loja_id&&r.periodo===mes);const chave=l.loja_id+'|'+x.periodicidade+'|'+x.periodo;const email=l.destinatarios?.email;let acao='ignorar',motivo='',assunto='',html='';
